~sq_cEntry_form~sq_cEntry Display Query.sql:
PARAMETERS __Mouse_Name Value;
SELECT DISTINCTROW *
FROM (SELECT [Entry Display Query].Entry_ID, [Entry Display Query].Mouse_Name, [Entry Display Query].Competition_Challenge, [Entry Display Query].Competition_Competition_Class, [Entry Display Query].Competition_Competition_Name FROM [Entry Display Query])  AS Entry_form
WHERE ([__Mouse_Name] = Mouse_Name);

~sq_cNew Contest~sq_cTodays_Competitions.sql:
PARAMETERS __Event_ID Value;
SELECT DISTINCTROW *
FROM (SELECT Todays_Competitions.Competition_Name, Todays_Competitions.Event_ID, Todays_Competitions.Competition_Class FROM Todays_Competitions)  AS [New Contest]
WHERE ([__Event_ID] = Event_ID);

~sq_cSequence_Competitions~sq_cEntry Sub.sql:
PARAMETERS __Competition_ID Value;
SELECT DISTINCTROW *
FROM Entry AS Sequence_Competitions
WHERE ([__Competition_ID] = Competition_ID);

