Best_Score_Times_for_current_Event.sql:
SELECT Best_Score_Time.ID, Best_Score_Time.Entry_ID, Best_Score_Time.Mouse_Name, Best_Score_Time.Contestant_Name, Best_Score_Time.Contestant_Class, Best_Score_Time.Score_Time_mS, Best_Score_Time.Run_Time_mS, Best_Score_Time.Competition_ID, Competition.Competition_Name, Competition.Challenge, Competition.Competition_Class, Competition.Event_ID
FROM Competition INNER JOIN Best_Score_Time ON Competition.[Competition_ID] = Best_Score_Time.[Competition_ID]
WHERE (((Competition.Event_ID)=[Forms]![Context_Form]![Event_ID]));

Best_Scores_for_selected_Competition.sql:
SELECT Best_Score_Time.Entry_ID, Best_Score_Time.Mouse_Name, Best_Score_Time.Contestant_Name, Best_Score_Time.Contestant_Class, Best_Score_Time.Score_Time_mS, Best_Score_Time.Run_Time_mS, Best_Score_Time.Competition_ID
