WHERE (Best_Score_Time.Competition_ID = [Comp_ID]);

Check_Retirements.sql:
SELECT Entry.*, Best_Score_Time.Score_Time_mS, Best_Score_Time.Run_Time_mS
FROM Entry LEFT JOIN Best_Score_Time ON Entry.Entry_ID = Best_Score_Time.Entry_ID
WHERE (((Entry.Competition_ID) IN (SELECT Competition_ID FROM Competition WHERE Competition.Event_ID = [Forms]![Context_Form]![Event_ID])));

Competitions_for_current_Event.sql:
SELECT Competition.Competition_ID, Competition.Event_ID, Competition.Competition_Name, Competition.Challenge, Competition.Competition_Class, Competition.Competition_Date, Competition.Scoring_Model_Short_Name, Competition.Entry_Time_Limit_Secs
FROM Competition
WHERE (((Competition.Event_ID)=[Forms]![Context_Form]![Event_ID]));

Delete_Unnamed_Entry_Runs.sql:
DELETE *
FROM Entry_Run
WHERE (Entry_Run.Entry_ID IN (SELECT  Best_Score_Time.Entry_ID FROM Best_Score_Time WHERE Best_Score_Time.Contestant_Class = "_"));

Entry Display Query.sql:
SELECT Entry.Entry_ID, Entry.Mouse_Name, Entry.Competition_ID AS Entry_Competition_ID, Competition.Event_ID, Competition.Challenge AS Competition_Challenge, Competition.Competition_Class AS Competition_Competition_Class, Competition.Competition_Date AS Competition_Competition_Date, Competition.Competition_Name AS Competition_Competition_Name
FROM Competition INNER JOIN Entry ON Competition.[Competition_ID] = Entry.[Competition_ID]
WHERE Competition.Event_ID=Forms![Context_Form].Event_ID;

event_results.sql:
SELECT Best_Score_Time.ID, Context.Current_Event, Competition.Challenge, Best_Score_Time.Contestant_Class, Competition.Competition_Class, Competition.Competition_Name, Best_Score_Time.Mouse_Name, Best_Score_Time.Contestant_Name, Best_Score_Time.Score_Time_mS
FROM Context INNER JOIN (Competition INNER JOIN Best_Score_Time ON Competition.[Competition_ID] = Best_Score_Time.[Competition_ID]) ON Context.Current_Event_ID = Competition.Event_ID
ORDER BY Competition.Challenge, Best_Score_Time.Contestant_Class, Competition.Competition_Class DESC , Best_Score_Time.Score_Time_mS;

Extended_Entries_Extract_for_current_Eve.sql:
SELECT Entry.Entry_ID, Entry.Mouse_Name AS Robot, Entry.Competition_ID AS C_ID, Competition.Competition_Name AS Contest, Competition.Challenge AS Challenge, Competition.Competition_Class AS Class, Entry.Registration_Source AS Source, Contestant.Contestant_Name AS Contestant, Contestant.Class AS Cont_Level, Mouse.Further_Information AS Team_Information
FROM Contestant INNER JOIN (Mouse INNER JOIN (Competition INNER JOIN Entry ON Competition.[Competition_ID] = Entry.[Competition_ID]) ON Mouse.Mouse_Name = Entry.Mouse_Name) ON Contestant.Contestant_ID = Mouse.Contestant_ID
WHERE (((Competition.Event_ID)=[Forms]![Context_Form]![Event_ID]));

