FROM Contestant INNER JOIN Mouse ON Contestant.Contestant_ID = Mouse.Contestant_ID
WHERE (((Mouse.Mouse_Name)="Asymouse"));

Get_Entries_for_a_Contest.sql:
SELECT Entry.Entry_ID, Entry.Mouse_Name, Entry.Competition_ID, Entry.Sequence_Number
FROM Entry
WHERE (((Entry.Competition_ID)=[Entry_Contest_ID]));

Get_entry_form_challenge.sql:
SELECT Todays_Competitions.Challenge
