Rank_Query.sql:
SELECT Rank
FROM (SELECT Mouse_Name, (SELECT COUNT(T1.Score_Time_mS) FROM (SELECT Best_Score_Time.Entry_ID, Best_Score_Time.Mouse_Name, Best_Score_Time.Contestant_Name, Best_Score_Time.Contestant_Class, Best_Score_Time.Score_Time_mS, Best_Score_Time.Run_Time_mS, Best_Score_Time.Competition_ID FROM Best_Score_Time WHERE (Best_Score_Time.Competition_ID = [Comp_ID])) AS T1 WHERE T1.Score_Time_mS <= T2.Score_Time_mS) AS Rank FROM (SELECT Best_Score_Time.Entry_ID, Best_Score_Time.Mouse_Name, Best_Score_Time.Contestant_Name, Best_Score_Time.Contestant_Class, Best_Score_Time.Score_Time_mS, Best_Score_Time.Run_Time_mS, Best_Score_Time.Competition_ID FROM Best_Score_Time WHERE (Best_Score_Time.Competition_ID = [Comp_ID]))  AS T2 ORDER BY Score_Time_mS)  AS [%$##@_Alias]
WHERE (Mouse_Name = [Mouse]);

Run_Times_for_current_Event.sql:
SELECT Competition.Challenge, Competition.Competition_Class, Competition.Competition_Name, Entry.Mouse_Name, Contestant.Contestant_Name, Contestant.Class, Entry_Run.Run_Time_mSecs, Entry_Run.Course_Time_mSecs, Entry_Run.Touches, Entry_Run.Score_Time_mSecs, Entry_Run.Date_of_Run, Entry_Run.Time_of_Run
FROM Competition INNER JOIN ((Contestant INNER JOIN Mouse ON Contestant.Contestant_ID = Mouse.Contestant_ID) INNER JOIN (Entry_Run INNER JOIN Entry ON Entry_Run.Entry_ID = Entry.Entry_ID) ON Mouse.Mouse_Name = Entry.Mouse_Name) ON Competition.Competition_ID = Entry.Competition_ID
WHERE (((Competition.Event_ID)=[forms]![Context_Form]![Event_ID]));

