FROM Competition INNER JOIN Entry ON Competition.[Competition_ID] = Entry.[Competition_ID]
WHERE (((Competition.Event_ID)=[Forms]![Context_Form]![Event_ID]) AND (Entry.Entry_Used = FALSE));

Used_Entries_Contest_Name_Scores_Current.sql:
